const input = $('Execute Workflow Trigger').first().json;
const c = $input.first()?.json ?? {};
const now = Date.now();
const expired = c.expires_at ? new Date(c.expires_at).getTime() < now : false;
const stale = c.processing_lock && c.locked_at ? (now - new Date(c.locked_at).getTime()) > 10*60*1000 : false;
return [{json:{...input,context:{exists:Boolean(c.state),state:c.state ?? 'new',status:c.status ?? 'active',payload:c.payload ?? {},processing_lock:Boolean(c.processing_lock),expired,stale}}}];
